import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 size 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const BASES = ['전체', '월별'];
const MONTH = /^[0-9]{4}-(0[1-9]|1[0-2])$/;

// 조회 유형별 결과 조건 (키는 허용된 조회 유형만, 값은 고정 SQL 조각)
const REPORT_FILTER: Record<string, string> = {
  '감가상각비 현황': 'TRUE',
  '고정자산 명세서': 'TRUE',
  '변동 현황': 't."changeAmount" <> 0',
  '관리대장': 'TRUE',
  '미상각자산 감가상각 명세서': 't."monthsDone" < t."usefulLifeMonths"',
};

// 가정: 감가상각비는 정액법(월 균등)으로 계산한다. (취득원가 - 잔존가액) / 내용연수(개월), 취득월부터 상각.
// 전체 기준 = 기준 기간 끝 월까지의 누적 상각비, 월별 기준 = 기준 기간 안의 상각비.
// 가정: 기간 중 증감 금액 = (기간 중 취득한 자산의 취득원가) - (기간 중 감가상각비).
// 가정: 기준월을 안 주면 현재 월, 기간은 'YYYY-MM' 또는 'YYYY-MM~YYYY-MM'.
const BASE = `
  SELECT
    q.asset_code AS "assetCode",
    q.asset_name AS "assetName",
    q.account_subject_id AS "accountSubjectId",
    q.acquisition_date AS "acquisitionDate",
    q.acquisition_cost AS "acquisitionCost",
    q.depreciation_method AS "depreciationMethod",
    q.useful_life_months AS "usefulLifeMonths",
    q.m_end AS "monthsDone",
    CAST(CASE WHEN CAST(:basis AS text) = '월별'
      THEN q.monthly * (q.m_end - q.m_before)
      ELSE q.monthly * q.m_end END AS numeric(18,2)) AS "depreciationAmount",
    CAST((CASE WHEN q.acq_in_period THEN q.acquisition_cost ELSE 0 END)
      - q.monthly * (q.m_end - q.m_before) AS numeric(18,2)) AS "changeAmount"
  FROM (
    SELECT
      a.asset_code, a.asset_name, a.account_subject_id,
      d.acquisition_date, d.acquisition_cost, d.depreciation_method, d.useful_life_months,
      (d.acquisition_cost - COALESCE(d.salvage_value, 0)) / d.useful_life_months AS monthly,
      LEAST(d.useful_life_months, GREATEST(0, CAST((EXTRACT(YEAR FROM p.to_d) * 12 + EXTRACT(MONTH FROM p.to_d)) - (EXTRACT(YEAR FROM d.acquisition_date) * 12 + EXTRACT(MONTH FROM d.acquisition_date)) AS integer) + 1)) AS m_end,
      LEAST(d.useful_life_months, GREATEST(0, CAST((EXTRACT(YEAR FROM p.from_d) * 12 + EXTRACT(MONTH FROM p.from_d)) - (EXTRACT(YEAR FROM d.acquisition_date) * 12 + EXTRACT(MONTH FROM d.acquisition_date)) AS integer))) AS m_before,
      (d.acquisition_date >= p.from_d AND d.acquisition_date < p.to_d + interval '1 month') AS acq_in_period
    FROM asset a
    JOIN asset_depreciation d ON d.asset_id = a.asset_id
    CROSS JOIN (
      SELECT
        CAST(COALESCE(CAST(:fromMonth AS text), to_char(now(), 'YYYY-MM')) || '-01' AS date) AS from_d,
        CAST(COALESCE(CAST(:toMonth AS text), CAST(:fromMonth AS text), to_char(now(), 'YYYY-MM')) || '-01' AS date) AS to_d
    ) p
    WHERE (CAST(:assetCode AS text) IS NULL OR a.asset_code = CAST(:assetCode AS text))
      AND (CAST(:accountSubjectId AS bigint) IS NULL OR a.account_subject_id = CAST(:accountSubjectId AS bigint))
  ) q
`;

function textOf(v: unknown): string | null {
  if (v === undefined || v === null) return null;
  if (typeof v !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 조건의 형식이 올바르지 않습니다.');
  }
  const s = v.trim();
  return s === '' ? null : s;
}

function wholeNumber(v: unknown, label: string): number | null {
  const s = textOf(v);
  if (s === null) return null;
  if (!/^[0-9]+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값은 숫자여야 합니다.');
  }
  return Number(s);
}

@Controller('api/v1')
export class FnSfr01102Controller {
  @Get('/asset-reports')
  async listAssetReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자', '예산·회계 담당자');
    const query = checks.queryOf(req.query);

    const reportType = textOf(query['reportType']);
    if (reportType === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 유형을 선택해 주세요.');
    }
    const reportFilter = REPORT_FILTER[reportType];
    if (reportFilter === undefined) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 유형이 올바르지 않습니다.');
    }
    const basis = textOf(query['basis']) ?? '전체';
    if (!BASES.includes(basis)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기준은 전체 또는 월별이어야 합니다.');
    }

    let fromMonth: string | null = null;
    let toMonth: string | null = null;
    const baseMonth = textOf(query['baseMonth']);
    if (baseMonth !== null) {
      const parts = baseMonth.split('~').map((s) => s.trim());
      const valid = (parts.length === 1 || parts.length === 2) && parts.every((s) => MONTH.test(s));
      if (!valid || (parts.length === 2 && parts[0] > parts[1])) {
        throw new ApiError(422, 'INVALID_PERIOD_FORMAT', '조회 기간 형식이 올바르지 않습니다. 예: 2025-03 또는 2025-01~2025-06');
      }
      fromMonth = parts[0];
      toMonth = parts.length === 2 ? parts[1] : parts[0];
    }

    const assetCode = textOf(query['assetCode']);
    if (assetCode !== null && assetCode.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자산코드는 50자 이하여야 합니다.');
    }
    const accountSubjectId = wholeNumber(query['accountSubjectId'], '계정과목');
    const page = wholeNumber(query['page'], 'page') ?? 0;
    const size = Math.min(wholeNumber(query['size'], 'size') ?? DEFAULT_SIZE, MAX_SIZE);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size는 1 이상이어야 합니다.');
    }

    const filterParams = {
      basis,
      fromMonth,
      toMonth,
      assetCode,
      accountSubjectId,
    };

    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT t."assetCode", t."assetName", t."accountSubjectId", t."acquisitionDate",
          t."acquisitionCost", t."depreciationMethod", t."usefulLifeMonths",
          t."depreciationAmount", t."changeAmount"
        FROM (${BASE}) t
        WHERE ${reportFilter}
        ORDER BY t."assetCode"
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...filterParams, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM (${BASE}) t WHERE ${reportFilter}`,
        filterParams,
      );
      return {
        items: rows,
        page,
        size,
        total: Number(counts[0]['total']),
      };
    });
  }
}

