import { useState } from 'react';
import {
  Band,
  DataTable,
  DateText,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  Pairs,
  RefName,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const REPORT_TYPES: [string, string][] = [
  ['감가상각비 현황', '감가상각비 현황'],
  ['고정자산 명세서', '고정자산 명세서'],
  ['변동 현황', '고정자산 변동 현황'],
  ['관리대장', '고정자산 관리대장'],
  ['미상각자산 감가상각 명세서', '미상각자산 감가상각 명세서'],
];

const BASES: [string, string][] = [
  ['전체', '전체'],
  ['월별', '월별'],
];

const MONTH = /^[0-9]{4}-(0[1-9]|1[0-2])$/;
const SIZE = 20;

const INITIAL: Row = {
  reportType: '고정자산 명세서',
  basis: '전체',
  baseMonth: '',
  assetCode: '',
  accountSubjectId: '',
};

function periodOk(text: string): boolean {
  if (text.trim() === '') return true;
  const parts = text.split('~').map((s) => s.trim());
  if (parts.length > 2) return false;
  if (!parts.every((s) => MONTH.test(s))) return false;
  return parts.length === 1 || parts[0] <= parts[1];
}

export default function FnSfr01102Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>(INITIAL);
  const [applied, setApplied] = useState<Row>(INITIAL);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/asset-reports', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );

  const set = (key: string, value: unknown) => setDraft({ ...draft, [key]: value });

  const search = () => {
    if (!periodOk(String(draft.baseMonth ?? ''))) {
      setFormError('조회 기간 형식이 올바르지 않습니다. 예: 2025-03 또는 2025-01~2025-06');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied(draft);
  };

  const reset = () => {
    setFormError('');
    setDraft(INITIAL);
    setPage(0);
    setApplied(INITIAL);
  };

  if (selected) {
    return (
      <div className='doc'>
        <button className='ghost' onClick={() => setSelected(null)}>
          목록으로 돌아가기
        </button>
        <section className='box'>
          <h2>자산 정보</h2>
          <Pairs
            items={[
              ['자산코드', String(selected.assetCode ?? '')],
              ['자산명', String(selected.assetName ?? '')],
              ['계정과목', <RefName table='account_subject' role={role} value={selected.accountSubjectId} />],
            ]}
          />
        </section>
        <section className='box'>
          <h2>감가상각 정보</h2>
          <Pairs
            items={[
              ['취득일', <DateText value={selected.acquisitionDate} />],
              ['취득원가', <Num value={selected.acquisitionCost} />],
              ['감가상각 방법', String(selected.depreciationMethod ?? '')],
              ['내용연수(개월)', <Num value={selected.usefulLifeMonths} />],
              ['감가상각비', <Num value={selected.depreciationAmount} />],
              ['기간 중 증감 금액', <Num value={selected.changeAmount} />],
            ]}
          />
        </section>
      </div>
    );
  }

  return (
    <div className='doc'>
      <h1>고정자산 현황·명세 조회</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label='조회 유형' required>
          <Select
            value={draft.reportType}
            onChange={(v) => set('reportType', v)}
            options={REPORT_TYPES}
            placeholder='조회 유형 선택'
          />
        </Field>
        <Field label='감가상각비 현황 기준'>
          <Select value={draft.basis} onChange={(v) => set('basis', v)} options={BASES} />
        </Field>
        <Field label='조회 기준월 또는 기간' hint='예: 2025-03 또는 2025-01~2025-06'>
          <TextInput value={draft.baseMonth} onChange={(v) => set('baseMonth', v)} />
        </Field>
        <Field label='자산코드'>
          <TextInput value={draft.assetCode} onChange={(v) => set('assetCode', v)} />
        </Field>
        <Field label='계정과목'>
          <LookupSelect
            table='account_subject'
            role={role}
            value={draft.accountSubjectId}
            onChange={(v) => set('accountSubjectId', v)}
            placeholder='전체'
          />
        </Field>
      </Filters>
      {formError ? <ErrorText text={formError} /> : null}
      {error ? <ErrorText text={error} /> : null}
      <Band total={data?.total} />
      <DataTable
        columns={[
          { key: 'assetCode', label: '자산코드' },
          { key: 'assetName', label: '자산명' },
          {
            key: 'accountSubjectId',
            label: '계정과목',
            render: (row) => <RefName table='account_subject' role={role} value={row.accountSubjectId} />,
          },
          {
            key: 'acquisitionCost',
            label: '취득원가',
            render: (row) => <Num value={row.acquisitionCost} />,
          },
          {
            key: 'depreciationAmount',
            label: '감가상각비',
            render: (row) => <Num value={row.depreciationAmount} />,
          },
        ]}
        rows={data?.items ?? []}
        onRowClick={(row) => setSelected(row)}
        empty={loading ? '불러오는 중입니다.' : '조회 결과가 없습니다. 조건을 바꿔 다시 조회해 주세요.'}
      />
      <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
    </div>
  );
}
